    "verified": true,
    "taskId": "1.2",
    "taskTitle": "Design secure workloads and applications",
    "inShort": "Security Groups are stateful allow-only instance firewalls; NACLs are stateless subnet firewalls that alone can DENY a specific IP.",
    "triggers": [
      {
        "when": "explicitly block/deny a specific malicious IP or CIDR at the subnet",
        "pick": "Network ACL deny rule (SGs cannot deny anything)"
      },
      {
        "when": "NACL response packets dropped / clients time out despite inbound allow",
        "pick": "Add outbound NACL allow for ephemeral ports 1024-65535 (NACLs are stateless)"
      },
      {
        "when": "filter Layer-7 HTTP attacks (SQLi, XSS, geo) or rate-limit abusive clients on ALB/CloudFront/API Gateway",
        "pick": "AWS WAF with managed rule groups + rate-based rule"
      },
      {
        "when": "private subnets must reach S3 or DynamoDB with no internet path and no NAT data charges",
        "pick": "Gateway VPC endpoints (free; S3 and DynamoDB only)"
      },
      {
        "when": "allow one tier to reach another where instances autoscale and IPs keep changing",
        "pick": "Reference the source Security Group in the destination SG rule"
      },
      {
        "when": "admin private instances with no inbound SSH/RDP, no bastion, IAM-controlled and logged",
        "pick": "SSM Session Manager"
      }
    ]
