    "taskTitle": "Design cost-optimized storage solutions",
    "inShort": "Match the storage class and tool to the access pattern; how fast, how often, and how many AZs you need decides the cheapest fit.",
    "triggers": [
      {
        "when": "infrequent access but still needs instant (millisecond) retrieval AND multi-AZ durability",
        "pick": "S3 Standard-IA"
      },
      {
        "when": "data is reproducible, a secondary copy, or non-critical AND infrequently accessed",
        "pick": "S3 One Zone-IA (~20% cheaper, single AZ)"
      },
      {
        "when": "access pattern is unknown, changing, or spiky AND you want zero retrieval fees / no lifecycle rules to maintain",
        "pick": "S3 Intelligent-Tiering"
      },
      {
        "when": "long-term archive, rarely retrieved, and hours-long retrieval (up to ~12hr) is acceptable",
        "pick": "S3 Glacier Deep Archive (lowest cost)"
      },
      {
        "when": "large one-time offline migration over a slow/saturated link",
        "pick": "Snowball Edge; use DataSync for ongoing scheduled online sync"
      },
      {
        "when": "visualize/forecast spend vs alert on a cost threshold",
        "pick": "Cost Explorer (visualize/forecast) + Budgets (alerts)"
      }
    ]
